<script setup lang="ts">
import {settingsSchema,type Settings,type Operator} from '#shared/model'
const {state,ready,startFree,busy}=useLearning(),settings=ref<Settings>(JSON.parse(JSON.stringify(state.value.lastSettings))),error=ref('')
const mixedRecognition=ref(false),knownOperators=computed(()=>new Set(state.value.sessions.flatMap(s=>s.questions.filter(q=>s.attempts.some(a=>a.questionId===q.id)).map(q=>q.operator)))),eligibleOperators=computed(()=>settings.value.operators.filter((op):op is Operator=>knownOperators.value.has(op)))
watch(ready,loaded=>{if(loaded)settings.value=JSON.parse(JSON.stringify(state.value.lastSettings))})
async function start(){error.value='';try{const parsed=settingsSchema.safeParse(settings.value);if(!parsed.success)throw new Error('연산을 한 개 이상 선택하고 문제 수를 1~100으로 설정해 주세요.');const selected=mixedRecognition.value?{...parsed.data,operators:eligibleOperators.value}:parsed.data;if(!selected.operators.length||mixedRecognition.value&&selected.operators.length<2)throw new Error('혼합 연습에 포함할 수 있는 학습 기록이 없어요. 먼저 한 가지 연산을 집중해서 풀어 보세요.');const id=await startFree(selected,mixedRecognition.value,parsed.data);await navigateTo(`/learn?id=${id}`)}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="page narrow-page"><div class="eyebrow">PRACTICE YOUR WAY</div><h1>자유 학습</h1><p class="page-intro">연습하고 싶은 계산을 직접 골라 보세요.</p><p v-if="!ready" class="muted" role="status">저장한 학습 조건을 불러오고 있어요…</p><form v-else class="form-surface" @submit.prevent="start"><SettingsFields v-model="settings"/><label class="mixed-option"><input v-model="mixedRecognition" type="checkbox" :disabled="eligibleOperators.length<2"><span><b>연산 판단 혼합 연습</b><small>문제에서 연산 기호를 감추고 직접 고르게 해요. 선택한 연산 중 이전 학습 기록이 있는 유형만 섞습니다.</small><small v-if="mixedRecognition">포함 유형: {{eligibleOperators.map(op=>({add:'덧셈',subtract:'뺄셈',multiply:'곱셈',divide:'나눗셈'})[op]).join(' · ')||'선택된 기록 없음'}}</small><small v-else-if="eligibleOperators.length<2">먼저 각 연산을 한 번 이상 학습해 주세요.</small></span></label><p v-if="error" class="alert" role="alert">{{error}}</p><div class="form-footer"><span>{{settings.count}}문제 · 시간 제한 없음</span><button class="btn" :disabled="busy" type="submit">학습 시작<AppIcon name="arrow" :size="18"/></button></div></form><p class="muted footnote">문제 수, 자릿수, 난이도, 받아올림·나머지 조건을 그대로 적용해요.</p></div></template>
